UPDATE t_client_application
SET status='UNDER_REVIEW', due_diligence_case_id=#{caseId}, update_time=#{now}
WHERE application_id=#{applicationId} AND current_submission_id=#{submissionId} AND status='SUBMITTED'

UPDATE t_client_application
SET status=#{status}, qualification_decision_id=#{decisionId}, update_time=#{now}
  , active_slot=NULL
WHERE application_id=#{row.applicationId} AND status='UNDER_REVIEW'
  AND current_submission_id=#{row.currentSubmissionId} AND due_diligence_case_id=#{row.dueDiligenceCaseId}
